/**
 * Generate the /mr and /hi route trees from the English one.
 *
 *   npm run i18n:routes
 *
 * Every public page under src/app gets a sibling under src/app/mr and
 * src/app/hi that re-exports it. The page itself is never duplicated — the
 * generated file is four lines and says where the real one is.
 *
 * Why generated rather than written by hand: twenty-eight pages times two
 * languages is fifty-six files nobody will keep in step, and the day somebody
 * adds a page the other two languages quietly lose it. This is run after
 * adding a page, and the result is checked in so the build needs no codegen.
 *
 * Why not move everything under src/app/[locale] instead: English would move
 * from /products to /en/products, every indexed URL would change, and every
 * internal <Link> in the project would need a prefix. This keeps English
 * exactly where it is.
 */

import {
  existsSync,
  mkdirSync,
  readFileSync,
  readdirSync,
  rmSync,
  statSync,
  writeFileSync,
} from "node:fs";
import { dirname, join, relative, sep } from "node:path";

const APP = "src/app";
const LOCALES = ["mr", "hi"];

/* Not pages of the site: the admin is one language, and the generated trees
   must not generate themselves. */
const SKIP = new Set(["admin", ...LOCALES]);

/** Every public route file, relative to src/app. */
function routes(dir = APP, found = []) {
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) {
      if (SKIP.has(entry)) continue;
      routes(full, found);
    } else if (entry === "page.tsx") {
      found.push(relative(APP, full).split(sep).join("/"));
    }
  }
  return found;
}

const pages = routes();
console.log(`${pages.length} public pages`);

for (const locale of LOCALES) {
  /* Cleared first: a page deleted in English must not linger in Marathi, and
     a stale route would still build and still be reachable. */
  rmSync(join(APP, locale), { recursive: true, force: true });

  for (const page of pages) {
    const target = join(APP, locale, page);
    mkdirSync(dirname(target), { recursive: true });

    /* The @/ alias rather than a relative path: counting ../ from a nested
       dynamic route is a sum to get wrong, and I did get it wrong. */
    const source = `@/app/${page.replace(/\.tsx$/, "")}`;

    /* Read, not assumed. Pages differ: some export `metadata`, some a
       `generateMetadata` function, some neither, and re-exporting one that is
       not there fails the build.

       A plain string, not a template literal: `\s` inside a template literal
       is the letter s, which turned this regex into one that matched nothing
       and silently produced routes with no generateStaticParams. */
    const code = readFileSync(join(APP, page), "utf8");
    const has = (name) =>
      new RegExp("export\\s+(?:async\\s+)?(?:const|function)\\s+" + name + "\\b").test(code);

    const exports = ["default"];
    for (const name of ["metadata", "generateMetadata", "generateStaticParams", "dynamicParams", "revalidate"]) {
      if (has(name)) exports.push(name);
    }

    writeFileSync(
      target,
      `/* Generated by scripts/i18n-routes.mjs. Do not edit.
` +
        `   The page itself lives at src/app/${page}. */

` +
        `export { ${exports.join(", ")} } from "${source}";
`,
      "utf8",
    );
  }

  console.log(`  src/app/${locale}  ${pages.length} routes`);
}

/* not-found and the other specials are not pages and are not copied: Next
   resolves those from the root for every path. */
if (!existsSync(join(APP, "mr"))) {
  console.error("x  nothing was generated");
  process.exitCode = 1;
}
